package com.covoiturage.api.dto.response; public class VehiculeResponse { private int idVehicule; private String marque; private String modele; private String immatriculation; private int nbPlaces; public VehiculeResponse() {} public VehiculeResponse(int idVehicule,String marque,String modele,String immatriculation,int nbPlaces){this.idVehicule=idVehicule;this.marque=marque;this.modele=modele;this.immatriculation=immatriculation;this.nbPlaces=nbPlaces;} public int getIdVehicule(){return idVehicule;} public void setIdVehicule(int v){idVehicule=v;} public String getMarque(){return marque;} public void setMarque(String v){marque=v;} public String getModele(){return modele;} public void setModele(String v){modele=v;} public String getImmatriculation(){return immatriculation;} public void setImmatriculation(String v){immatriculation=v;} public int getNbPlaces(){return nbPlaces;} public void setNbPlaces(int v){nbPlaces=v;} }
